import React,{useRef,useState} from 'react';
import {Alert,Image,KeyboardAvoidingView,Platform,Pressable,ScrollView,Share,StyleSheet,Text,TextInput,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {Ionicons} from '@/platform/icons';
import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query';
import {useVideoPlayer,VideoView} from '@/platform/video';
import {SafeAreaView} from '@/platform/safe-area';
import {api} from '@/lib/api';
import {Avatar,Badge,EmptyState,Muted,useAppTheme} from '@/components/UI';
import {LinkText} from '@/components/LinkText';

type Reaction='LIKE'|'CELEBRATE'|'SUPPORT';
type Post={Id:string;Body:string;PostType:string;MediaUrl?:string;MediaType?:string;Caption?:string;CreatedAt:string;FirstName:string;LastName:string;ProfileImage?:string;ReactionCount:number;CommentCount:number;ShareCount:number;MyReaction?:Reaction;MySaved?:boolean};
type Comment={Id:string;Body:string;ParentCommentId?:string;CreatedAt:string;FirstName:string;LastName:string;ProfileImage?:string;LikeCount:number;DislikeCount:number;MyReaction?:'LIKE'|'DISLIKE'};

export default function PostDetail(){
 const{id,postId}=useLocalSearchParams<{id:string;postId:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const inputRef=useRef<TextInput>(null);const[body,setBody]=useState('');const[reply,setReply]=useState<Comment|null>(null);
 const feed=useQuery<Post[]>({queryKey:['feed',id],queryFn:async()=>(await api.get(`/communities/${id}/feed`)).data});
 const post=feed.data?.find(item=>item.Id===postId);
 const comments=useQuery<Comment[]>({queryKey:['post-comments',postId],enabled:!!postId,queryFn:async()=>(await api.get(`/posts/${postId}/comments`)).data});
 const refresh=()=>{qc.invalidateQueries({queryKey:['feed',id]});qc.invalidateQueries({queryKey:['post-comments',postId]})};
 const react=useMutation({mutationFn:async()=>api.post(`/posts/${postId}/reaction`,{reaction:post?.MyReaction==='LIKE'?null:'LIKE'}),onSuccess:refresh});
 const save=useMutation({mutationFn:async()=>api.post(`/posts/${postId}/save`),onSuccess:refresh});
 const add=useMutation({mutationFn:async()=>api.post(`/posts/${postId}/comments`,{body:body.trim(),parentCommentId:reply?.Id}),onSuccess:()=>{setBody('');setReply(null);refresh()},onError:()=>Alert.alert('Unable to comment','Please try again.')});
 const reactComment=useMutation({mutationFn:async({item,reaction}:{item:Comment;reaction:'LIKE'|'DISLIKE'})=>api.post(`/comments/${item.Id}/reaction`,{reaction:item.MyReaction===reaction?null:reaction}),onSuccess:refresh});
 const share=async()=>{if(!post)return;await api.post(`/posts/${post.Id}/share`);await Share.share({message:`${post.FirstName} ${post.LastName} on CDA Connect:\n\n${post.Body}`});refresh()};
 if(feed.isLoading)return <View style={[s.center,{backgroundColor:palette.background}]}><Muted>Loading post…</Muted></View>;
 if(!post)return <View style={[s.center,{backgroundColor:palette.background}]}><EmptyState icon="document-outline" title="Post unavailable" body="This post may have been removed."/></View>;
 return <KeyboardAvoidingView style={[s.page,{backgroundColor:palette.background}]} behavior={Platform.OS==='ios'?'padding':undefined}><SafeAreaView edges={['top']} style={{backgroundColor:palette.surface}}><View style={[s.header,{borderBottomColor:palette.border,backgroundColor:palette.surface}]}><Pressable accessibilityLabel="Back to feed" onPress={()=>router.back()} style={s.touch}><Ionicons name="chevron-back" size={27} color={palette.text}/></Pressable><Text style={[s.headerTitle,{color:palette.text}]}>Post</Text><View style={s.touch}/></View></SafeAreaView><ScrollView style={{flex:1}} contentContainerStyle={s.content} keyboardShouldPersistTaps="handled"><View style={[s.post,{backgroundColor:palette.surface,borderBottomColor:palette.border}]}><View style={s.authorRow}><Avatar name={`${post.FirstName} ${post.LastName}`} uri={post.ProfileImage} size={46}/><View style={{flex:1}}><Text style={[s.author,{color:palette.text}]}>{post.FirstName} {post.LastName}</Text><Muted>{new Date(post.CreatedAt).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}</Muted></View><Badge text={post.PostType.replace('_',' ')} tone="gray"/></View>{post.Body?<LinkText style={[s.body,{color:palette.text}]}>{post.Body}</LinkText>:null}<PostMedia post={post}/>{post.Caption?<Muted style={s.caption}>{post.Caption}</Muted>:null}<View style={[s.stats,{borderColor:palette.border}]}><Muted>{post.ReactionCount} reactions · {post.CommentCount} comments · {post.ShareCount} shares</Muted></View><View style={s.actions}><Action icon={post.MyReaction?'thumbs-up':'thumbs-up-outline'} label="Like" active={!!post.MyReaction} onPress={()=>react.mutate()} palette={palette}/><Action icon="chatbubble-outline" label="Comment" onPress={()=>inputRef.current?.focus()} palette={palette}/><Action icon="share-social-outline" label="Share" onPress={()=>void share()} palette={palette}/><Action icon={post.MySaved?'bookmark':'bookmark-outline'} label="Save" active={!!post.MySaved} onPress={()=>save.mutate()} palette={palette}/></View></View><View style={s.commentsHeader}><Text style={[s.commentsTitle,{color:palette.text}]}>All comments</Text><Ionicons name="chevron-down" size={18} color={palette.text}/></View>{comments.isLoading?<Muted style={s.loading}>Loading comments…</Muted>:comments.data?.length?comments.data.map(item=><View key={item.Id} style={[s.comment,item.ParentCommentId&&s.replyComment]}><Avatar name={`${item.FirstName} ${item.LastName}`} uri={item.ProfileImage} size={38}/><View style={{flex:1}}><View style={s.nameRow}><Text style={[s.commentName,{color:palette.text}]}>{item.FirstName} {item.LastName}</Text><Muted> · {new Date(item.CreatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</Muted></View><LinkText style={[s.commentBody,{color:palette.text}]}>{item.Body}</LinkText><Pressable accessibilityLabel={`Reply to ${item.FirstName}`} onPress={()=>setReply(item)}><Muted style={s.replyLabel}>Reply</Muted></Pressable></View><View style={s.votes}><Vote icon={item.MyReaction==='LIKE'?'thumbs-up':'thumbs-up-outline'} count={item.LikeCount} active={item.MyReaction==='LIKE'} onPress={()=>reactComment.mutate({item,reaction:'LIKE'})} palette={palette}/><Vote icon={item.MyReaction==='DISLIKE'?'thumbs-down':'thumbs-down-outline'} count={item.DislikeCount} active={item.MyReaction==='DISLIKE'} onPress={()=>reactComment.mutate({item,reaction:'DISLIKE'})} palette={palette}/></View></View>):<Muted style={s.loading}>No comments yet. Start the conversation.</Muted>}</ScrollView>{reply?<View style={[s.replying,{backgroundColor:palette.primarySoft}]}><Text style={{color:palette.text,flex:1}}>Replying to {reply.FirstName}</Text><Pressable onPress={()=>setReply(null)}><Ionicons name="close" size={18} color={palette.text}/></Pressable></View>:null}<View style={[s.composer,{backgroundColor:palette.surface,borderTopColor:palette.border}]}><TextInput ref={inputRef} value={body} onChangeText={setBody} placeholder="Add a comment…" placeholderTextColor={palette.muted} returnKeyType="send" onSubmitEditing={()=>body.trim()&&!add.isPending&&add.mutate()} style={[s.input,{color:palette.text,borderColor:palette.border}]}/><Pressable disabled={!body.trim()||add.isPending} accessibilityLabel="Send comment" onPress={()=>add.mutate()} style={[s.send,{backgroundColor:body.trim()?palette.primary:palette.border}]}><Ionicons name="send" size={19} color="#fff"/></Pressable></View></KeyboardAvoidingView>;
}

function PostMedia({post}:{post:Post}){if(!post.MediaUrl)return null;if(post.PostType==='PHOTO')return <Image source={{uri:post.MediaUrl}} resizeMode="contain" style={s.media}/>;if(post.PostType==='VIDEO')return <PostVideo uri={post.MediaUrl}/>;return null}
function PostVideo({uri}:{uri:string}){const player=useVideoPlayer(uri,p=>{p.loop=false});return <VideoView player={player} nativeControls contentFit="contain" style={s.media}/>}
function Action({icon,label,onPress,active=false,palette}:{icon:keyof typeof Ionicons.glyphMap;label:string;onPress:()=>void;active?:boolean;palette:any}){return <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress} style={s.action}><Ionicons name={icon} size={21} color={active?palette.primary:palette.muted}/><Text style={{color:active?palette.primary:palette.muted,fontWeight:'800'}}>{label}</Text></Pressable>}
function Vote({icon,count,onPress,active,palette}:{icon:keyof typeof Ionicons.glyphMap;count:number;onPress:()=>void;active:boolean;palette:any}){return <Pressable accessibilityRole="button" onPress={onPress} style={s.vote}><Ionicons name={icon} size={18} color={active?palette.primary:palette.muted}/>{count?<Muted>{count}</Muted>:null}</Pressable>}

const s=StyleSheet.create({page:{flex:1},center:{flex:1,alignItems:'center',justifyContent:'center',padding:24},header:{height:68,paddingHorizontal:8,borderBottomWidth:1,flexDirection:'row',alignItems:'center',justifyContent:'space-between'},touch:{width:46,height:46,alignItems:'center',justifyContent:'center'},headerTitle:{fontSize:20,fontWeight:'900'},content:{paddingBottom:28},post:{padding:16,borderBottomWidth:1},authorRow:{flexDirection:'row',alignItems:'center',gap:10},author:{fontSize:15,fontWeight:'900'},body:{fontSize:15,lineHeight:21,marginTop:13},media:{width:'100%',height:360,marginTop:12,backgroundColor:'#050505'},caption:{marginTop:8},stats:{paddingVertical:12,borderBottomWidth:1},actions:{height:52,flexDirection:'row'},action:{flex:1,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:5},commentsHeader:{height:54,paddingHorizontal:17,flexDirection:'row',alignItems:'center',gap:5},commentsTitle:{fontSize:15,fontWeight:'900'},loading:{padding:24,textAlign:'center'},comment:{flexDirection:'row',gap:9,paddingHorizontal:16,marginBottom:20,alignItems:'flex-start'},replyComment:{marginLeft:30},nameRow:{flexDirection:'row',alignItems:'center',flexWrap:'wrap'},commentName:{fontSize:13,fontWeight:'900'},commentBody:{fontSize:14,lineHeight:20,marginVertical:4},replyLabel:{fontSize:12,fontWeight:'700',marginTop:4},votes:{flexDirection:'row',gap:8},vote:{minWidth:35,height:35,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:3},replying:{height:36,marginHorizontal:10,paddingHorizontal:12,borderRadius:10,flexDirection:'row',alignItems:'center'},composer:{height:62,paddingHorizontal:12,paddingVertical:8,borderTopWidth:1,flexDirection:'row',alignItems:'center',gap:8},input:{flex:1,height:44,borderWidth:1,borderRadius:22,paddingHorizontal:15,fontSize:14},send:{width:44,height:44,borderRadius:22,alignItems:'center',justifyContent:'center'}});
